// Auto-generated preloaded assets for Geometry Dash photo skins and billboards

export const GD_SKIN_PHOTO_1 = 'data:image/jpeg;base64,';
export const GD_SKIN_PHOTO_2 = 'data:image/jpeg;base64,';
export const GD_SKIN_PHOTO_3 = 'data:image/jpeg;base64,';

export const GD_BILLBOARD_PHOTO_1 = 'data:image/jpeg;base64,';
export const GD_BILLBOARD_PHOTO_2 = 'data:image/jpeg;base64,';
export const GD_BILLBOARD_PHOTO_3 = 'data:image/jpeg;base64,';

export const GD_ASSET_IMAGES: Record<string, HTMLImageElement> = {};

if (typeof window !== 'undefined') {
  const assets: Record<string, string> = {
    [GD_SKIN_PHOTO_1]: GD_SKIN_PHOTO_1,
    [GD_SKIN_PHOTO_2]: GD_SKIN_PHOTO_2,
    [GD_SKIN_PHOTO_3]: GD_SKIN_PHOTO_3,
    [GD_BILLBOARD_PHOTO_1]: GD_BILLBOARD_PHOTO_1,
    [GD_BILLBOARD_PHOTO_2]: GD_BILLBOARD_PHOTO_2,
    [GD_BILLBOARD_PHOTO_3]: GD_BILLBOARD_PHOTO_3,
    // Friendly key aliases
    skin_1: GD_SKIN_PHOTO_1,
    skin_2: GD_SKIN_PHOTO_2,
    skin_3: GD_SKIN_PHOTO_3,
    bb_1: GD_BILLBOARD_PHOTO_1,
    bb_2: GD_BILLBOARD_PHOTO_2,
    bb_3: GD_BILLBOARD_PHOTO_3,
  };

  for (const [key, src] of Object.entries(assets)) {
    try {
      const img = new Image();
      img.src = src;
      GD_ASSET_IMAGES[key] = img;
    } catch {}
  }
}
